===== mcp__pixellab__animate_image
exec tool declaration:
```ts
declare const tools: { mcp__pixellab__animate_image(args: {
  // The motion (e.g. 'walking forward', 'flame flickering', 'chest opening'). Describe movement, not appearance.
  action: string;
  // Base64 PNG to animate � the first frame. Max 256x256. PREFER first_frame_url; MCP clients routinely truncate large inline base64.
  first_frame_base64?: string | null;
  // Alternative to first_frame_base64: an https (or data:) URL to the first frame PNG. PREFER THIS. Give one, not both.
  first_frame_url?: string | null;
  // Frames to generate � must be EVEN. 4 for idle loops, 8 for walk/run, 16 for complex actions. Large frames allow fewer frames.
  frame_count?: number;
  // Optional final frame, same size as the first, to pin where the motion ends (interpolation instead of open-ended animation).
  last_frame_base64?: string | null;
  // Alternative to last_frame_base64: an https (or data:) URL to the final frame PNG. Give one, not both.
  last_frame_url?: string | null;
  // Background handling. Default (unset) follows the first frame: a transparent sprite animates on transparency, an opaque image stays opaque.
  no_background?: boolean | null;
  // Internal Game Builder project context; the finished image is linked after generation.
  project_id?: string | null;
  // Seed for reproducible generation.
  seed?: number | null;
}): Promise<CallToolResult>; };
```

===== mcp__pixellab__pixelart_workbench
exec tool declaration:
```ts
declare const tools: { mcp__pixellab__pixelart_workbench(args: {
  // One command line, e.g. 'lint <drawing_id> --rules outline_gap' or ['edit', '<id>', '--changes', '[�]']. Omit it for the playbook. A subject is an id or an image reference � never a file path; the server writes the output and returns a new id. A reference is `character:<id>:<direction>` for a rotation, `character:<id>:<direction>:<animation>` for every frame of that animation (the display name, type or [group: ...] id get_character prints), the same two forms for `object:<id>` (a one-direction object's direction is the literal `unknown`), `gallery:<id>`, `job:<id>`, `upload:<id>`, a data URL, an https link or base64. That is how a stored animation's pixels come back inline without downloading anything. Start with 'describe cli' for the full command list.
  argv?: string | Array<string> | null;
  // low (default): act directly, fewest tokens � one decisive image per result. high: think openly � fuller evidence and a review checklist; write your plan and observations in `notes`. Use the mode the user asked for.
  mode?: "low" | "high";
  // What you observed and what this step should achieve, in a few sentences (high mode: always; low: optional). On the first call, include the user's request. Stored with the step to improve these tools.
  notes?: string | null;
}): Promise<CallToolResult>; };
```

===== mcp__pixellab__create_image_pro_flash
exec tool declaration:
```ts
declare const tools: { mcp__pixellab__create_image_pro_flash(args: {
  description: string;
  height?: number;
  // At most this many colours in the image (2-64). With a palette, they are picked from it.
  max_colors?: number | null;
  no_background?: boolean;
  // Target palette, 2 to 256 hex colours as a JSON array, e.g. ["#081820", "#346856", "#88c070", "#e0f8d0"] for Game Boy or ["#000000", "#ffffff"] for 1-bit. The image is drawn for these colours and every pixel of the result is one of them.
  palette?: Array<string> | null;
  // Optional name of the palette (e.g. 'Game Boy', 'PICO-8'); naming it helps the look.
  palette_name?: string | null;
