hexs=lambda p: '#%02x%02x%02x%02x'%p
expected=set()
for k in range(1,4):
    for y in range(16):
        for x in range(16):
            a=seed(x,y); b=cwk(x,y,k)
            if a!=b: expected.add((16*k+x,y,hexs(a),hexs(b)))
pol=json.load(open('work/authoring-01/working-rotation-policy.json',encoding='utf-8'))
